      const r = { id: want, score: Math.min(1, g.progress), accepted: true, reason: "\xEDm\xE3", ranking: [{ id: want, score: Math.min(1, g.progress) }], strokes: g.strokes.length, margin: 1 };
      this.attempt = { strokes: g.litStrokes(), raw: [], result: r, expected: want, ms: 0, why, bridges: g.bridges };
      this.ui.drawDebug(this.attempt);
      this.ui.setMeter(r.score, `runa tra\xE7ada: ${pct3}% \xB7 precis\xE3o ${acc}%`);
